const sourceMap=Object.fromEntries(SOURCES.map(s=>[s.id,s]));
const rows=[];
function add(subject,topic,day,prompt,correct,wrong,explanation,memory,recall,source){
 const n=rows.length+1,choices=[correct,...wrong],shift=n%4;
 const rotated=choices.slice(shift).concat(choices.slice(0,shift));
 rows.push({id:`night-${String(n).padStart(3,'0')}`,subject,topic,day,prompt,choices:rotated,answer:rotated.indexOf(correct),explanation,memory,recall,source:sourceMap[source].name,sourceUrl:sourceMap[source].url,sourceId:source,custom:false});
}
