add(1,'자산배분',3,'목표 비중이 주식 60%·채권 40%였는데 주가 상승 후 75%·25%가 됐다. 리밸런싱의 목적은?', '원래 정한 위험 수준에 맞춰 비중을 조정하기', ['다음 달 수익을 보장하기','항상 주식 비중을 늘리기','거래비용을 무조건 0으로 만들기'], '자산 가격이 바뀌면 포트폴리오 위험 노출도 변해요. 리밸런싱은 목표 비중으로 조정하는 것이며 수익 보장 전략은 아니에요.', '리밸런싱 = 목표 위험으로 되돌리기.', '가격이 변하면 비중과 위험도 그대로일까요?', 'allocation');
add(1,'채권 기초',3,'채권의 만기 전에 팔 때 받을 가격에 대한 설명으로 가장 적절한 것은?', '시장금리와 신용상태 등에 따라 매입가격보다 낮을 수 있다', ['발행 시점 가격과 항상 같다','매입가격보다 반드시 높다','만기 전에는 가격이 존재하지 않는다'], '만기상환 약정과 중도매도 가격은 달라요. 금리가 오르거나 신용상태가 악화되면 중도매도 손실이 생길 수 있어요.', '만기 약속과 중간 시장가격은 다르다.', '중도매도와 만기보유를 구별해보세요.', 'bonds');
add(1,'채권 기초',3,'채권에서 표면금리의 직접적인 역할은?', '액면금액을 기준으로 약정 이자를 계산하는 기준', ['언제나 실제 투자수익률을 보장하는 값','중도 매도가격을 고정하는 값','물가상승률을 정하는 값'], '표면금리는 액면금액에 대한 약정 이자의 기준이에요. 실제 매입가격이 액면가와 다르면 투자자의 수익률과 표면금리는 달라질 수 있어요.', '표면은 액면의 이자, 수익률은 투자한 가격도 본다.', '같은 이자를 받아도 비싸게 산 사람과 싸게 산 사람의 수익률은 같을까요?', 'bonds');

add(2,'수익률',1,'100만원을 투자해 1년 뒤 105만원에 팔고, 그동안 분배금 3만원을 받았다. 세금·비용을 무시한 보유기간 수익률은?', '8%', ['5%','3%','108%'], '(기말가치−기초가치+분배금)÷기초가치 = (105−100+3)÷100 = 8%예요.', '수익률 분자에는 가격변화 + 받은 현금.', '가격 차익 말고 받은 현금이 있나요?', 'portfolio');
add(2,'기대수익률',1,'수익률이 50% 확률로 +20%, 50% 확률로 −10%다. 기대수익률은?', '5%', ['10%','15%','−5%'], '가능한 수익률에 각각 확률을 곱해 더해요. 0.5×20% + 0.5×(−10%) = 5%예요.', '기대값 = 확률로 가중평균.', '두 시나리오의 확률 합이 1인지 확인해보세요.', 'portfolio');
add(2,'포트폴리오',1,'자산 A 60%, B 40%로 투자했다. 기대수익률이 각각 10%, 5%라면 포트폴리오 기대수익률은?', '8%', ['7.5%','15%','6%'], '0.6×10% + 0.4×5% = 6% + 2% = 8%예요. 기대수익률은 투자 비중으로 가중평균해요.', '비중 × 수익률을 더한다.', '단순평균인가요, 투자 비중을 반영한 평균인가요?', 'portfolio');
add(2,'위험',1,'포트폴리오 이론에서 베타가 주로 나타내는 것은?', '시장 움직임에 대한 수익률의 민감도', ['모든 위험의 합계','한 해의 확정 수익률','채권의 표면금리'], '베타는 시장수익률과 함께 움직이는 정도를 측정해요. 총위험을 나타내는 표준편차와 구분해야 해요.', '베타는 시장에 대한 민감도.', '베타와 표준편차는 무엇을 각각 재나요?', 'portfolio');
add(2,'위험',1,'종목을 충분히 분산해도 남는 시장 전체의 공통 위험은?', '체계적 위험', ['비체계적 위험','개별기업 고유 위험','회사의 단일 공장 화재 위험만'], '경기·금리 변화처럼 시장 전체에 영향을 주는 위험은 분산만으로 없애기 어려워요. 개별기업 고유 위험은 분산으로 줄일 수 있어요.', '체계 = 시장 공통, 비체계 = 개별 고유.', '시장 전체 위험과 한 회사의 위험을 나눠보세요.', 'portfolio');
add(2,'상관관계',1,'다른 조건이 같을 때 두 자산의 상관계수가 +1에서 0으로 낮아지면 분산 효과는 일반적으로?', '커진다', ['작아진다','반드시 없어진다','원금보장이 된다'], '덜 같은 방향으로 움직일수록 한 자산의 흔들림을 다른 자산이 일부 상쇄할 여지가 커져요. 그렇다고 모든 위험이 사라지는 것은 아니에요.', '덜 같이 움직일수록 분산의 여지가 커진다.', '두 자산이 늘 똑같이 움직이면 서로를 보완할까요?', 'portfolio');
add(2,'샤프지수',1,'위험조정 성과를 계산할 때 샤프지수의 분모는?', '수익률의 표준편차', ['베타','주가','배당금'], '샤프지수 = (포트폴리오 수익률−무위험수익률)÷포트폴리오 표준편차예요. 총위험 1단위당 초과수익을 봐요.', '샤프는 σ, 트레이너는 β.', '총위험을 나타내는 지표는 무엇인가요?', 'performance');
add(2,'CAPM',1,'무위험수익률 3%, 시장 기대수익률 8%, 베타 1.2다. CAPM 기대수익률은?', '9%', ['9.6%','6%','11%'], '3% + 1.2×(8%−3%) = 3%+6% = 9%예요. 베타를 곱할 대상은 시장수익률 전체가 아닌 시장위험프리미엄이에요.', '무위험 + 베타 × 시장 초과수익.', '베타는 시장수익률 전체에 곱하나요, 초과수익에 곱하나요?', 'portfolio');
add(2,'수익률',2,'첫해 +20%, 둘째 해 −20%였다. 최초 100만원의 2년 뒤 가치는? 비용은 무시한다.', '96만원', ['100만원','104만원','80만원'], '100×1.2×0.8 = 96만원이에요. 수익률의 단순 합은 0이지만 실제 자산은 4% 줄어요.', '연속 수익률은 더하지 말고 곱한다.', '20% 하락의 기준 금액은 원래 100만원일까요?', 'portfolio');
add(2,'트레이너지수',2,'수익률 10%, 무위험수익률 2%, 베타 1인 포트폴리오의 트레이너지수는?', '0.08', ['0.10','0.02','8.00'], '(0.10−0.02)÷1 = 0.08이에요. 수익률은 소수로 넣었어요. 분모를 표준편차로 바꾸면 샤프지수가 돼요.', '트레이너 = 초과수익 ÷ 베타.', '분모가 표준편차인지 베타인지 먼저 고르세요.', 'performance');
add(2,'샤프지수',2,'수익률 12%, 무위험수익률 2%, 표준편차 20%일 때 샤프지수는?', '0.5', ['0.6','2.0','5.0'], '(0.12−0.02)÷0.20 = 0.5예요. 분자·분모를 같은 단위로 계산하면 돼요.', '샤프 = 초과수익 ÷ 표준편차.', '무위험수익률을 빼는 것을 잊지 않았나요?', 'performance');
add(2,'젠센 알파',2,'실제 수익률 11%, 무위험수익률 3%, 시장수익률 8%, 베타 1이다. 젠센 알파는?', '+3%p', ['+8%p','+2%p','−3%p'], 'CAPM 기준 수익률은 3%+1×(8%−3%)=8%예요. 알파는 실제 11%−기준 8%=+3%p예요.', '알파 = 실제 수익률 − CAPM 기준.', '먼저 CAPM으로 기준 수익률을 구해보세요.', 'performance');
add(2,'CAPM',2,'시장위험프리미엄이 양수일 때, CAPM에서 베타가 높아지면 요구수익률은?', '높아진다', ['낮아진다','항상 0이 된다','언제나 그대로다'], '요구수익률 = 무위험수익률 + 베타×시장위험프리미엄이에요. 양수인 프리미엄에 더 큰 베타를 곱하면 요구수익률도 커져요.', '시장 프리미엄이 양수라면 β ↑ → 요구수익률 ↑', '베타에 곱하는 값의 부호를 확인해보세요.', 'portfolio');
add(2,'분산',2,'두 자산의 상관계수가 −1이고 적절한 비중을 선택할 수 있다. 이론상 가능한 설명은?', '두 위험자산만으로도 변동성을 완전히 상쇄할 수 있다', ['분산효과가 전혀 없다','두 자산은 항상 같은 방향으로 움직인다','어떤 비중에서도 수익률이 무조건 같다'], '완전한 음의 상관관계라면 두 자산의 반대 움직임을 적절한 비중으로 상쇄할 수 있어요. 현실에서 그런 관계가 안정적으로 유지된다고 보장되지는 않아요.', '−1은 반대 움직임, 비중이 맞아야 상쇄.', '완전히 반대로 움직이면 비중 조정으로 무엇을 할 수 있나요?', 'portfolio');
add(2,'포트폴리오',2,'A와 B의 표준편차는 각각 20%, 10%, 상관계수는 0이다. 각각 50% 투자할 때 분산은?', '0.0125', ['0.0225','0.15','0.05'], '분산 = 0.5²×0.2² + 0.5²×0.1² + 2×0.5×0.5×0.2×0.1×0 = 0.0125예요. 표준편차는 이 값의 제곱근으로 약 11.18%예요.', '분산은 비중도 제곱, 표준편차도 제곱.', '상관계수가 0이면 공분산 항은 어떻게 되나요?', 'portfolio');
add(2,'시장선',2,'CAPM의 증권시장선(SML)에서 가로축에 해당하는 것은?', '베타', ['총위험 표준편차','채권의 만기','주식의 액면가'], 'SML은 개별자산과 포트폴리오의 체계적 위험인 베타와 기대수익률의 관계를 나타내요. CML의 가로축인 표준편차와 구분해요.', 'SML은 β, CML은 σ.', 'SML과 CML의 가로축을 짝지어보세요.', 'portfolio');
add(2,'분산투자',3,'시장 전체가 하락할 때 대부분 주식이 함께 하락했다. 이때 공통으로 작용한 위험은?', '체계적 위험', ['분산하면 반드시 사라지는 고유위험','한 기업의 회계오류만','무위험수익률 그 자체'], '여러 기업이 함께 영향을 받는 시장 위험은 분산만으로 제거하기 어려워요. 회사 수를 늘리는 것과 시장 위험을 없애는 것은 달라요.', '회사 수를 늘려도 시장 자체는 남는다.', '모든 회사가 동시에 흔들리는 원인은 개별 위험일까요?', 'portfolio');
add(2,'트레이너지수',3,'A와 B의 양의 초과수익률이 같고 베타가 양수다. A의 베타가 더 작다면 트레이너지수는?', 'A가 더 크다', ['B가 더 크다','항상 같다','계산할 수 없고 어떤 비교도 불가능하다'], '같은 양의 초과수익을 더 작은 양의 베타로 나누면 값이 커져요. 체계적 위험 1단위당 보상을 비교하는 상황이에요.', '같은 보상이라면 작은 위험이 유리.', '분자는 같고 양수일 때 분모가 작아지면 값은?', 'performance');
add(2,'성과평가',3,'수익률이 더 높다는 사실만으로 운용성과가 더 우수하다고 단정하기 어려운 이유는?', '감수한 위험과 비교 기준이 다를 수 있어서', ['수익률은 항상 허구라서','위험은 누구에게나 같아서','모든 자산의 투자기간이 같아서'], '높은 수익이 더 큰 위험을 감수한 결과일 수 있어요. 투자기간과 벤치마크, 위험을 함께 보아야 성과를 비교할 수 있어요.', '수익만 말고 그 수익을 얻은 위험도.', '같은 10%라도 위험이 두 배라면 같은 성과인가요?', 'performance');
add(2,'베타',3,'포트폴리오가 A 40%, B 60%로 구성되고 각 베타가 1.5, 0.5다. 포트폴리오 베타는?', '0.9', ['1.0','2.0','0.6'], '베타는 비중으로 가중평균해요. 0.4×1.5 + 0.6×0.5 = 0.6+0.3 = 0.9예요.', '포트폴리오 β = 비중 × 개별 β의 합.', '투자 비중과 각 베타를 곱해보세요.', 'portfolio');
add(2,'샤프지수',3,'A와 B의 양의 초과수익률이 같고 표준편차도 양수다. A의 표준편차가 더 작다면?', 'A의 샤프지수가 더 높다', ['B의 샤프지수가 더 높다','두 샤프지수는 항상 1이다','샤프지수는 베타로만 정해진다'], '같은 양의 초과수익을 작은 표준편차로 나누면 샤프지수가 더 높아져요. 분모가 베타인 지표와 혼동하지 마세요.', '샤프의 위험은 표준편차.', '총위험이 작고 보상이 같다면 어떤 쪽이 유리할까요?', 'performance');
add(2,'상관관계',3,'두 위험자산의 상관계수가 +1이다. 공매도를 하지 않고 둘 다 양의 비중으로 투자할 때 분산 효과는?', '위험 상쇄 효과가 제한된다', ['항상 무위험이 된다','비중과 무관하게 위험이 0이다','두 자산은 완전히 반대로 움직인다'], '완전히 같은 방향으로 움직이므로 서로의 변동을 상쇄하기 어려워요. 이 경우 포트폴리오 표준편차는 개별 표준편차의 비중 가중평균이 돼요.', '+1은 함께 움직임, 상쇄가 어렵다.', '동시에 오르고 내리면 서로의 위험을 상쇄할까요?', 'portfolio');
add(2,'CAPM',3,'CAPM에서 베타가 0인 자산의 기대수익률은? 모형이 성립한다고 가정한다.', '무위험수익률', ['시장 기대수익률','항상 0%','시장 기대수익률의 두 배'], '무위험수익률 + 0×시장위험프리미엄 = 무위험수익률이에요. 베타가 0이라고 모든 종류의 위험이 없다는 뜻은 아니에요.', 'β=0이면 CAPM의 시장위험 보상은 0.', '0이 되는 것은 전체 식인가요, 시장위험 보상 항인가요?', 'portfolio');

add(3,'듀레이션',1,'다른 조건이 같을 때 고정금리 채권의 듀레이션이 클수록 금리 변화에 따른 가격 민감도는?', '크다', ['작다','항상 0이다','금리와 같은 방향으로만 움직인다'], '듀레이션은 금리 변화에 대한 채권 가격 민감도를 이해하는 지표예요. 수정듀레이션이 클수록 같은 금리 변화에서 가격 변동이 크게 추정돼요.', '듀레이션이 길수록 금리 충격에 더 크게 흔들린다.', '오래 묶인 현금흐름은 금리 변화에 더 민감할까요?', 'bonds');
add(3,'옵션',1,'콜옵션 매수자가 갖는 기본 권리는?', '정해진 조건에 따라 기초자산을 살 권리', ['기초자산을 반드시 살 의무','기초자산을 팔 권리','매도자에게 프리미엄을 받을 권리'], '콜은 살 권리, 풋은 팔 권리예요. 매수자는 프리미엄을 지급하고 권리를 얻으며 행사할 의무는 없어요.', '콜 = 사기, 풋 = 팔기.', '콜과 풋은 각각 사는 권리인가요, 파는 권리인가요?', 'options');
add(3,'옵션',1,'풋옵션 매수자가 갖는 기본 권리는?', '정해진 조건에 따라 기초자산을 팔 권리', ['반드시 살 의무','이자를 받을 권리','옵션 매수자에게 추가 프리미엄을 요구할 권리'], '풋 매수자는 정해진 행사가격에 팔 수 있는 권리를 얻어요. 기초자산 가격이 하락할 때 이 권리의 내재가치가 커질 수 있어요.', '풋은 가격이 떨어질 때 팔 권리의 가치.', '싼 시장가격 대신 높은 약정가격에 팔 수 있다면?', 'options');
add(3,'옵션',1,'옵션 매수자의 최대 손실에 대한 기본 설명은? 단순 옵션 매수이며 비용과 다른 포지션은 무시한다.', '지급한 프리미엄으로 제한된다', ['항상 무한대다','기초자산 가격 전체다','행사가격의 두 배다'], '매수자는 불리하면 행사하지 않을 수 있어요. 이미 낸 프리미엄을 잃을 수 있지만 추가 의무를 지는 단순 매도 포지션과 달라요.', '매수자는 권리, 최대 손실은 낸 값.', '불리한 권리는 꼭 행사해야 하나요?', 'options');
add(3,'선물',1,'선물계약과 옵션계약의 기본 차이로 적절한 것은?', '선물은 계약상 의무, 옵션 매수자는 행사할 권리', ['선물은 권리만 있고 옵션 매수자는 반드시 행사한다','둘 다 원금보장이다','둘 다 프리미엄만 잃을 수 있다'], '선물은 양 당사자가 계약상 의무를 부담해요. 옵션은 매수자가 권리를, 매도자가 그 행사에 응할 의무를 가지는 구조예요.', '선물은 약속, 옵션 매수는 선택권.', '행사하지 않을 선택권은 누구에게 있을까요?', 'options');
add(3,'헤지',1,'이미 주식을 보유한 투자자가 단기 주가 하락 위험을 줄이려고 주가지수선물을 이용한다. 기본적인 헤지 방향은?', '선물 매도', ['선물 매수','기초주식 추가 매수만','헤지와 방향은 무관'], '보유 주식은 가격 하락 때 손실을 보므로, 하락 때 이익이 나는 선물 매도 포지션을 이용해 위험을 상쇄하려는 거예요. 실제 헤지에는 규모와 베이시스 위험도 고려해요.', '이미 보유 → 하락이 걱정 → 매도 헤지.', '주식이 떨어질 때 이익 나는 선물 방향은?', 'hedge');
add(3,'투자자 보호',1,'투자권유 과정에서 고객의 재산상황·투자경험·손실감수능력 등을 확인하는 핵심 목적은?', '고객에게 적합한 상품인지 판단하기', ['판매수수료만 극대화하기','고객의 손실 가능성을 숨기기','어떤 상품이든 서명만 받으면 팔기'], '적합성 판단은 소비자가 제공한 정보와 손실감수능력 등을 종합해 검토해요. 판매자의 목표나 서명 여부만으로 적합성을 대신할 수 없어요.', '적합성은 고객에게 맞는지.', '상품이 좋다는 말보다 먼저 누구의 상황을 봐야 하나요?', 'consumer');
add(3,'투자자 보호',1,'상품 설명에서 수익 가능성은 크게 강조하고 중요한 손실 위험은 생략했다. 가장 적절한 평가는?', '중요한 위험을 이해할 수 있게 설명해야 한다', ['수익만 설명하면 충분하다','고객이 서명하면 위험 설명은 불필요하다','어려운 용어를 많이 쓰면 충분하다'], '소비자가 상품의 주요 내용과 위험을 이해할 수 있도록 설명해야 해요. 형식적인 서명이나 전문용어 나열만으로 충분한 설명이 되는 것은 아니에요.', '설명은 서명 수집이 아니라 이해를 돕는 일.', '고객이 손실 위험을 이해하지 못해도 설명이 끝난 걸까요?', 'consumer');
add(3,'리밸런싱',1,'주식 60만원·채권 40만원이 목표 60:40 포트폴리오다. 주식만 80만원이 되었다. 총액 120만원에서 목표로 돌아가려면?', '주식 8만원을 줄여 채권으로 옮긴다', ['주식 8만원을 더 산다','채권 12만원을 줄인다','아무 변화가 없다'], '목표 주식은 120×60%=72만원, 채권은 48만원이에요. 현재 80·40에서 주식 8만원을 채권으로 옮기면 돼요. 세금·비용은 무시했어요.', '현재 총액 × 목표비중을 먼저.', '리밸런싱의 기준은 최초 총액인가요, 현재 총액인가요?', 'allocation');
add(3,'채권 전략',1,'장기 고정금리 채권 투자자가 금리 상승을 예상한다. 금리 민감도를 줄이기 위한 기본 방향은?', '포트폴리오 듀레이션을 줄인다', ['듀레이션을 늘린다','표면금리를 0으로 강제 변경한다','금리위험은 항상 무시한다'], '금리 상승은 기존 채권 가격에 하락 압력을 줘요. 듀레이션을 줄이면 동일 금리 변화에 대한 가격 민감도가 일반적으로 작아져요.', '금리 상승이 걱정되면 듀레이션을 짧게.', '금리 상승과 가격 하락, 그다음 줄여야 할 민감도는?', 'bonds');
add(3,'수정듀레이션',2,'수정듀레이션 4인 채권의 시장금리가 0.5%p 상승했다. 듀레이션만 이용한 가격변화율 근삿값은?', '−2%', ['+2%','−0.02%','−8%'], '가격변화율 ≈ −수정듀레이션×금리변화 = −4×0.005 = −0.02, 즉 −2%예요. 0.5%p를 소수 0.005로 바꿔요.', '마이너스 부호, %p는 소수로.', '0.5%p를 소수로 쓰면 얼마인가요?', 'bonds');
add(3,'수정듀레이션',2,'수정듀레이션 5인 채권에서 금리가 1%p 하락했다. 볼록성을 무시한 가격변화율 근삿값은?', '+5%', ['−5%','+0.05%','−1%'], '−5×(−0.01)=+0.05, 즉 +5%예요. 금리 하락이므로 가격은 상승 방향이에요.', '금리 하락은 음수, 앞의 마이너스와 만나 가격은 상승.', '금리 변화의 부호부터 정해보세요.', 'bonds');
add(3,'옵션 계산',2,'만기 기초자산 가격 120, 행사가격 100, 콜 매수 프리미엄 8이다. 단위당 만기 순손익은? 비용은 무시한다.', '+12', ['+20','−8','+28'], '콜 만기 지급액은 max(120−100,0)=20이에요. 매수 때 낸 프리미엄 8을 빼면 순손익은 12예요.', '콜 순손익 = max(S−K,0) − 프리미엄.', '권리의 지급액과 실제 순손익은 어떻게 다를까요?', 'options');
add(3,'옵션 계산',2,'만기 기초자산 가격 80, 행사가격 100, 풋 매수 프리미엄 6이다. 단위당 순손익은? 비용은 무시한다.', '+14', ['+20','−6','−26'], '풋 만기 지급액은 max(100−80,0)=20이에요. 프리미엄 6을 빼면 순손익은 14예요.', '풋 순손익 = max(K−S,0) − 프리미엄.', '풋은 행사가격에서 시장가격을 빼는 방향이에요.', 'options');
add(3,'옵션 계산',2,'행사가격 100인 콜옵션을 프리미엄 7에 샀다. 만기 손익분기 기초자산 가격은?', '107', ['93','100','7'], '콜 매수는 기초자산이 행사가격보다 프리미엄만큼 더 올라야 지불한 값을 회수해요. 100+7=107이에요.', '콜 손익분기 = 행사가격 + 프리미엄.', '콜의 지급액이 낸 프리미엄과 같아지는 가격은?', 'options');
add(3,'옵션 계산',2,'행사가격 100인 풋옵션을 프리미엄 7에 샀다. 만기 손익분기 기초자산 가격은?', '93', ['107','100','7'], '풋 매수의 지급액은 행사가격−기초자산 가격이에요. 100−S=7이므로 S=93이에요.', '풋 손익분기 = 행사가격 − 프리미엄.', '가격이 얼마까지 떨어져야 프리미엄을 회수하나요?', 'options');
add(3,'옵션 계산',2,'콜옵션의 행사가격은 100, 만기 기초자산 가격은 90이다. 콜 매수자가 받을 만기 지급액은?', '0', ['10','−10','90'], '90에 시장에서 살 수 있는데 100에 살 권리를 행사할 이유가 없어요. 만기 지급액은 max(90−100,0)=0이에요. 낸 프리미엄까지 돌려받는다는 뜻은 아니에요.', '불리한 권리는 행사하지 않는다.', '시장 90, 약정 100이라면 어디서 사는 게 유리할까요?', 'options');
add(3,'헤지',2,'3개월 뒤 원재료를 사야 하는 기업이 가격 상승 위험을 줄이려 한다. 선물의 기본 방향은?', '매수 헤지', ['매도 헤지','보유량을 무조건 두 배로','가격 상승 위험과 무관'], '미래에 사야 하는 사람은 가격 상승이 걱정이에요. 상승 때 이익 나는 선물 매수를 이용해 구매비용 상승을 상쇄하려는 거예요.', '앞으로 살 것 → 상승 걱정 → 매수 헤지.', '가격이 올라서 손해인 사람은 어떤 선물에서 보완 이익을 얻나요?', 'hedge');
add(3,'옵션 계산',2,'기초자산 110, 행사가격 100, 콜옵션 시장가격 14다. 이 콜옵션의 시간가치는?', '4', ['10','14','24'], '콜 내재가치는 max(110−100,0)=10이에요. 옵션가격 14에서 내재가치 10을 뺀 4가 시간가치예요.', '옵션가격 = 내재가치 + 시간가치.', '먼저 지금 행사했을 때의 가치를 구해보세요.', 'options');
add(3,'채권 전략',2,'금리변화가 아주 작을 때 가격 민감도를 1차 근사하는 지표와, 곡률을 보완하는 지표의 조합은?', '듀레이션과 볼록성', ['베타와 거래량','PER와 EPS','배당금과 표면금리'], '듀레이션은 금리 변화에 대한 1차 민감도를, 볼록성은 가격·수익률 곡선의 휘어짐을 보완해요. 큰 금리 변화에서는 듀레이션만의 근사 오차가 커질 수 있어요.', '직선 근사는 듀레이션, 곡선 보완은 볼록성.', '채권 가격과 수익률의 관계는 완벽한 직선일까요?', 'bonds');
add(3,'옵션 전략',3,'주식을 보유하면서 같은 주식의 풋옵션을 매수하는 보호적 풋의 기본 목적은?', '프리미엄을 내고 하락 손실을 제한하기', ['비용 없이 모든 손실을 없애기','상승 이익을 반드시 0으로 만들기','주식을 자동 매도하기'], '보유 주식이 하락해도 일정 가격에 팔 권리로 손실을 제한하려는 전략이에요. 보험처럼 프리미엄 비용이 들어요.', '보호적 풋 = 주식에 하락 보험.', '주가 하락 때 가치를 얻는 권리는 무엇인가요?', 'options');
add(3,'옵션 전략',3,'보유 주식에 대해 콜옵션을 매도하는 커버드콜의 기본적인 교환관계는?', '프리미엄을 받는 대신 상승 이익이 제한될 수 있다', ['하락 손실이 완전히 사라진다','상승 이익이 무한히 확대된다','프리미엄을 지급하고 하락 보험을 산다'], '콜을 매도하면 프리미엄을 받지만 상대방이 행사할 때 의무를 이행해야 해요. 주가가 크게 오르면 일정 수준 위의 상승 이익을 포기하게 돼요.', '커버드콜 = 프리미엄 수입과 상승 여력의 교환.', '살 권리를 다른 사람에게 팔면 큰 상승 때 무슨 일이 생길까요?', 'options');
